/// Nomes que nunca podem ser encerrados por aqui: processos essenciais do
/// Windows (encerrar derruba o sistema ou causa tela azul) e o próprio
/// FluxTweakers (incluindo o WebView2, que é a janela do app).
const PROTECTED_PROCESSES: &[&str] = &[
    "system", "system idle process", "registry", "memory compression", "smss.exe",
    "csrss.exe", "wininit.exe", "winlogon.exe", "services.exe", "lsass.exe",
    "svchost.exe", "dwm.exe", "explorer.exe", "fontdrvhost.exe", "sihost.exe",
    "taskhostw.exe", "ctfmon.exe", "conhost.exe", "audiodg.exe", "spoolsv.exe",
    "msmpeng.exe", "securityhealthservice.exe", "runtimebroker.exe",
    "searchhost.exe", "startmenuexperiencehost.exe", "shellexperiencehost.exe",
    "fluxtweakers.exe", "msedgewebview2.exe",
];

/// Encerra TODAS as instâncias de um app pelo nome (ex: todas as abas/processos
/// de "msedge.exe"), sem precisar abrir o Gerenciador de Tarefas. Roda só pra
/// apps do usuário — os essenciais do Windows e o próprio FluxTweakers são
/// bloqueados aqui no backend (a interface também esconde o botão neles).
#[tauri::command]
async fn kill_processes_by_name(name: String, state: State<'_, SysState>) -> Result<KillResult, String> {
    let name = name.trim().to_string();
    let valid = !name.is_empty()
        && name.len() <= 128
        && name.chars().all(|c| c.is_ascii_alphanumeric() || " ._-()[]+".contains(c));
    if !valid {
        return Err("Nome de processo inválido".to_string());
    }
    if PROTECTED_PROCESSES.iter().any(|p| p.eq_ignore_ascii_case(&name)) {
        return Err(format!("{name} é um processo protegido (essencial do Windows ou do próprio FluxTweakers)"));
    }

    // Conta as instâncias e a memória que elas usam ANTES de encerrar.
    let (instances, mem_bytes) = {
        let mut sys = state.0.lock().unwrap();
        sys.refresh_processes(ProcessesToUpdate::All, true);
        let mut n = 0u32;
        let mut bytes = 0u64;
        for p in sys.processes().values() {
            if p.name().to_string_lossy().eq_ignore_ascii_case(&name) {
                n += 1;
                bytes += p.memory();
            }
        }
        (n, bytes)
    };
    if instances == 0 {
        return Err(format!("{name} não está mais em execução"));
    }

    #[cfg(target_os = "windows")]
    {
        let output = tauri::async_runtime::spawn_blocking(move || {
            Command::new("taskkill")
                .args(["/F", "/IM", &name])
                .creation_flags(CREATE_NO_WINDOW)
                .output()
        })
        .await
        .map_err(|e| format!("Falha interna: {e}"))?
        .map_err(|e| format!("Não consegui executar o encerramento: {e}"))?;

        if !output.status.success() {
            return Err("O Windows negou o encerramento (o app pode exigir permissão de administrador)".to_string());
        }
    }
    #[cfg(not(target_os = "windows"))]
    {
        return Err("Disponível apenas no Windows".to_string());
    }

    Ok(KillResult {
        instances,
        freed_mb: ((mem_bytes as f64) / 1_048_576.0 * 10.0).round() / 10.0,
    })
}

#[derive(Serialize)]
struct RamDetails {
    total_gb: f64,
    used_gb: f64,
    free_mb: f64,
    cached_mb: f64,
    /// Standby List real (NtQuerySystemInformation) — a mesma leitura nativa
    /// e precisa que a limpeza de RAM já usa, diferente do "cached_mb" acima
    /// (que vem de um contador WMI mais amplo).
    standby_mb: f64,
    pressure_percent: f64,
    top_processes: Vec<ProcessMemInfo>,
}

/// Dados detalhados de memória pra aba RAM: total/uso/livre/cache reais,
/// e os processos que mais consomem RAM agora — pra mostrar exatamente
/// o que está pesando, não só um número solto.
#[tauri::command]
async fn get_ram_details(state: State<'_, SysState>) -> Result<RamDetails, String> {
    let (total, used, free, top_processes) = {
        let mut sys = state.0.lock().unwrap();
        sys.refresh_memory();
        sys.refresh_processes(ProcessesToUpdate::All, true);

        let total = sys.total_memory() as f64;
        let used = sys.used_memory() as f64;
        let free = sys.free_memory() as f64;

        let mut processes: Vec<ProcessMemInfo> = sys
            .processes()
            .values()
            .map(|p| ProcessMemInfo {
                name: p.name().to_string_lossy().to_string(),
                memory_mb: p.memory() as f64 / 1_048_576.0,
            })
            .filter(|p| p.memory_mb > 30.0) // ignora processos irrelevantes
            .collect();

        // soma processos com o mesmo nome (ex: várias abas/instâncias do mesmo app)
        let mut grouped: std::collections::HashMap<String, f64> = std::collections::HashMap::new();
        for p in processes.drain(..) {
            *grouped.entry(p.name).or_insert(0.0) += p.memory_mb;
        }
        let mut top_processes: Vec<ProcessMemInfo> = grouped
            .into_iter()
            .map(|(name, memory_mb)| ProcessMemInfo {
                name,
                memory_mb: (memory_mb * 10.0).round() / 10.0,
            })
            .collect();
        top_processes.sort_by(|a, b| b.memory_mb.partial_cmp(&a.memory_mb).unwrap());
        top_processes.truncate(8);

        (total, used, free, top_processes)
    };

    // Lê o contador real "Cache Bytes" do Windows (o mesmo que o Gerenciador de
    // Tarefas usa) em vez de estimar — assim o número realmente reflete o que
    // a limpeza afeta, e cai de verdade quando você limpa.
    let cached = tauri::async_runtime::spawn_blocking(read_cache_bytes_windows)
        .await
        .unwrap_or(0.0);
    #[cfg(target_os = "windows")]
    let standby_mb = tauri::async_runtime::spawn_blocking(standby_list_mb)
        .await
        .ok()
        .flatten()
        .unwrap_or(0) as f64;
    #[cfg(not(target_os = "windows"))]
    let standby_mb: f64 = 0.0;

    Ok(RamDetails {
        total_gb: (total / 1_073_741_824.0 * 10.0).round() / 10.0,
        used_gb: (used / 1_073_741_824.0 * 10.0).round() / 10.0,
        free_mb: (free / 1_048_576.0 * 10.0).round() / 10.0,
        cached_mb: (cached / 1_048_576.0 * 10.0).round() / 10.0,
        standby_mb,
        pressure_percent: if total > 0.0 { (used / total * 100.0 * 10.0).round() / 10.0 } else { 0.0 },
        top_processes,
    })
}

#[derive(Serialize, Clone)]
struct SystemStats {
    cpu_percent: f64,
    ram_used_gb: f64,
    ram_total_gb: f64,
    ram_percent: f64,
    gpu_percent: Option<f64>,
    disks: Vec<DiskInfo>,
    /// true só nos ciclos em que as leituras "lentas" (GPU, frequência real,
    /// cache) foram feitas — aí um valor None significa "não deu pra medir",
    /// e não "não foi lido neste ciclo".
    slow_read: bool,
    cpu_freq_ghz: Option<f64>,
    cpu_cores: Option<usize>,
    cpu_threads: usize,
    cached_gb: Option<f64>,
    uptime_secs: u64,
    /// atividade real do disco (0-100%, tempo ocupado) — o mesmo número que
    /// o Gerenciador de Tarefas mostra. NÃO é o quanto do disco está cheio
    /// (isso é o `percent` de cada DiskInfo, uma coisa bem diferente).
    disk_active_pct: Option<f64>,
}

/// Lê o uso real de CPU e RAM via sysinfo (biblioteca nativa, sem depender
/// de comandos externos — bem rápido, roda em memória). A checagem de GPU
/// é opcional (include_gpu) porque ela precisa abrir um processo do
/// PowerShell nos bastidores e é bem mais lenta — por isso só é chamada
/// de vez em quando pelo frontend, nunca a cada atualização.
#[tauri::command]
async fn get_system_stats(
    state: State<'_, SysState>,
    pdh_state: State<'_, PdhState>,
    include_gpu: bool,
) -> Result<SystemStats, String> {
    compute_system_stats(&state, &pdh_state, include_gpu).await
}

/// O mesmo cálculo de get_system_stats, só que como função comum (não um
/// tauri::command) — assim tanto o comando quanto o loop de monitoramento em
/// segundo plano (que roda independente da janela estar em foco) usam
/// exatamente a mesma lógica, sem duplicar nada.
async fn compute_system_stats(
    sys_state: &SysState,
    pdh_state: &PdhState,
    include_gpu: bool,
) -> Result<SystemStats, String> {
    let (cpu_percent, ram_used_gb, ram_total_gb, ram_percent, cpu_cores, cpu_threads) = {
        let mut sys = sys_state.0.lock().unwrap();
        sys.refresh_cpu_usage();
        sys.refresh_memory();
        let cpu_cores = sys.physical_core_count();
        let cpu_threads = sys.cpus().len();

        let cpu = sys.global_cpu_usage() as f64;
        let total = sys.total_memory() as f64 / 1_073_741_824.0;
        let used = sys.used_memory() as f64 / 1_073_741_824.0;
        let percent = if total > 0.0 { (used / total) * 100.0 } else { 0.0 };
        (cpu, used, total, percent, cpu_cores, cpu_threads)
    };
    let uptime_secs = System::uptime();

    let disks_list = Disks::new_with_refreshed_list();
    let disks: Vec<DiskInfo> = disks_list
        .iter()
        .map(|d| {
            let total = d.total_space() as f64 / 1_073_741_824.0;
            let avail = d.available_space() as f64 / 1_073_741_824.0;
            let used = (total - avail).max(0.0);
            let percent = if total > 0.0 { (used / total) * 100.0 } else { 0.0 };
            DiskInfo {
                name: d.mount_point().to_string_lossy().to_string(),
                used_gb: (used * 10.0).round() / 10.0,
                total_gb: (total * 10.0).round() / 10.0,
                percent: (percent * 10.0).round() / 10.0,
                is_ssd: d.is_removable() == false && matches!(d.kind(), sysinfo::DiskKind::SSD),
            }
        })
        .collect();

    // GPU, frequência REAL da CPU e cache não vêm do sysinfo (ele só dá a
    // frequência nominal, que parece "travada"). Vêm de contadores do Windows
    // lidos via WMI — o mesmo que o Gerenciador de Tarefas usa. Tudo numa
    // ÚNICA chamada de PowerShell (antes eram várias, e o próprio custo de abrir
    // PowerShell inflava o uso de CPU medido), e só de vez em quando.
    if !include_gpu {
        return Ok(SystemStats {
            cpu_percent: (cpu_percent * 10.0).round() / 10.0,
            ram_used_gb: (ram_used_gb * 10.0).round() / 10.0,
            ram_total_gb: (ram_total_gb * 10.0).round() / 10.0,
            ram_percent: (ram_percent * 10.0).round() / 10.0,
            gpu_percent: None,
            disks,
            slow_read: false,
            cpu_freq_ghz: None,
            cpu_cores,
            cpu_threads,
            cached_gb: None,
            uptime_secs,
            disk_active_pct: None,
        });
    }

    #[cfg(target_os = "windows")]
    let (gpu, cpu_mhz, disk_active, cpu_utility) = {
        let mut guard = pdh_state.0.lock().unwrap();
        read_pdh_metrics(&mut guard)
    };
    #[cfg(not(target_os = "windows"))]
    let (gpu, cpu_mhz, disk_active, cpu_utility): (
        Option<f64>,
        Option<f64>,
        Option<f64>,
        Option<f64>,
    ) = (None, None, None, None);

    #[cfg(target_os = "windows")]
    let cache_mb = tauri::async_runtime::spawn_blocking(standby_list_mb)
        .await
        .ok()
        .flatten();
    #[cfg(not(target_os = "windows"))]
    let cache_mb: Option<u64> = None;

    // "% Processor Utility" (via PDH) é o contador que o Gerenciador de
    // Tarefas realmente usa pra CPU — quando disponível, substitui o valor
    // do sysinfo (que usa o contador clássico "% Processor Time" e por isso
    // não reflete o turbo boost do jeito que o Windows mostra na tela).
    // A RAM continua 100% como estava, sem nenhuma mudança.
    let reported_cpu_percent = cpu_utility.unwrap_or(cpu_percent);

    Ok(SystemStats {
        cpu_percent: (reported_cpu_percent * 10.0).round() / 10.0,
        ram_used_gb: (ram_used_gb * 10.0).round() / 10.0,
        ram_total_gb: (ram_total_gb * 10.0).round() / 10.0,
        ram_percent: (ram_percent * 10.0).round() / 10.0,
        gpu_percent: gpu.map(|g| (g.clamp(0.0, 100.0) * 10.0).round() / 10.0),
        disks,
        slow_read: true,
        cpu_freq_ghz: cpu_mhz.filter(|m| *m > 0.0).map(|m| (m / 1000.0 * 100.0).round() / 100.0),
        cpu_cores,
        cpu_threads,
        cached_gb: cache_mb.map(|mb| ((mb as f64) / 1024.0 * 10.0).round() / 10.0),
        uptime_secs,
        disk_active_pct: disk_active.map(|d| (d.clamp(0.0, 100.0) * 10.0).round() / 10.0),
    })
}

/// ===== Monitor nativo via PDH (Performance Data Helper) =====
///
/// Antes, GPU/CPU-frequência/disco eram lidos abrindo um processo do
/// PowerShell a cada leitura — o que custa tempo (o próprio PowerShell demora
/// pra abrir) e por isso só rodava a cada alguns segundos, deixando esses
/// números "atrasados" na tela em comparação com o Gerenciador de Tarefas,
/// que atualiza a cada 1 segundo.
///
/// Agora a leitura é nativa: abre UMA ÚNICA conexão com a PDH (a mesma API
/// que o Gerenciador de Tarefas usa por baixo dos panos) quando o programa
/// inicia, e só CONSULTA esse canal já aberto a cada atualização — sem abrir
/// processo nenhum. Isso deixa GPU e disco tão rápidos quanto CPU/RAM.
#[cfg(target_os = "windows")]
struct PdhMonitor {
    query: isize,
    disk_counter: isize,
    cpu_counter: isize,
    /// "% Processor Utility" — o contador que o Gerenciador de Tarefas
    /// realmente usa pro número de CPU desde o Windows 10/11 recente
    /// (diferente do "% Processor Time" clássico, que o sysinfo usa). Ele
    /// já leva em conta o turbo boost, então reflete melhor o que a tela do
    /// Windows mostra. Fica em Option porque não existe em Windows mais
    /// antigos — nesse caso cai pro valor do sysinfo normalmente.
    cpu_utility_counter: Option<isize>,
    gpu_counter: Option<isize>,
    base_mhz: Option<f64>,
    /// contadores de "% de tempo" da PDH precisam de DUAS leituras pra dar um
    /// valor válido (a primeira é só a "largada" da amostra) — até isso
    /// acontecer, devolve None em vez de um número fabricado.
    primed: bool,
}
#[cfg(target_os = "windows")]
unsafe impl Send for PdhMonitor {}

#[cfg(target_os = "windows")]
#[repr(C)]
struct PdhFmtCounterValue {
    c_status: u32,
    _pad: u32,
    value: f64,
}

#[cfg(target_os = "windows")]
#[repr(C)]
struct PdhFmtCounterValueItemW {
    sz_name: *const u16,
    fmt_value: PdhFmtCounterValue,
}

#[cfg(target_os = "windows")]
#[link(name = "pdh")]
extern "system" {
    fn PdhOpenQueryW(data_source: *const u16, user_data: usize, query: *mut isize) -> u32;
    fn PdhAddEnglishCounterW(
        query: isize,
        full_counter_path: *const u16,
        user_data: usize,
        counter: *mut isize,
    ) -> u32;
    fn PdhCollectQueryData(query: isize) -> u32;
    fn PdhGetFormattedCounterValue(
        counter: isize,
        format: u32,
        counter_type: *mut u32,
        value: *mut PdhFmtCounterValue,
    ) -> u32;
    fn PdhGetFormattedCounterArrayW(
        counter: isize,
        format: u32,
        buffer_size: *mut u32,
        buffer_count: *mut u32,
        item_buffer: *mut PdhFmtCounterValueItemW,
    ) -> u32;
}

#[cfg(target_os = "windows")]
const PDH_FMT_DOUBLE: u32 = 0x00000200;

/// Lê a velocidade BASE da CPU (MHz) uma única vez, direto do Registro do
/// Windows — não muda em tempo de execução, então não precisa reler. Isso
/// evita precisar do WMI/PowerShell só pra essa informação fixa.
#[cfg(target_os = "windows")]
fn read_base_cpu_mhz() -> Option<f64> {
    unsafe {
        const HKEY_LOCAL_MACHINE: isize = 0x80000002u32 as i32 as isize;
        const RRF_RT_REG_DWORD: u32 = 0x00000010;
        let subkey: Vec<u16> = "HARDWARE\\DESCRIPTION\\System\\CentralProcessor\\0\0"
            .encode_utf16()
            .collect();
        let value_name: Vec<u16> = "~MHz\0".encode_utf16().collect();
        let mut data: u32 = 0;
        let mut data_len: u32 = 4;
        let status = RegGetValueW(
            HKEY_LOCAL_MACHINE,
            subkey.as_ptr(),
            value_name.as_ptr(),
            RRF_RT_REG_DWORD,
            std::ptr::null_mut(),
            &mut data as *mut u32 as *mut core::ffi::c_void,
            &mut data_len,
        );
        if status == 0 && data > 0 {
            Some(data as f64)
        } else {
            None
        }
    }
}

/// Abre a conexão com a PDH e registra os 3 contadores que vamos ler sempre
/// (GPU, CPU e disco) — roda UMA VEZ, na inicialização do programa. Se um
/// contador específico falhar ao ser adicionado (ex: driver de GPU que não
/// expõe esses dados), essa métrica fica None pra sempre, mas as outras
/// continuam funcionando normalmente.
#[cfg(target_os = "windows")]
fn init_pdh_monitor() -> Option<PdhMonitor> {
    unsafe {
        let mut query: isize = 0;
        if PdhOpenQueryW(std::ptr::null(), 0, &mut query) != 0 {
            return None;
        }

        let add_counter = |path: &str| -> Option<isize> {
            let wide: Vec<u16> = path.encode_utf16().chain(std::iter::once(0)).collect();
            let mut counter: isize = 0;
            if PdhAddEnglishCounterW(query, wide.as_ptr(), 0, &mut counter) == 0 {
                Some(counter)
            } else {
                None
            }
        };

        let disk_counter = add_counter(r"\PhysicalDisk(_Total)\% Idle Time")?;
        let cpu_counter = add_counter(r"\Processor Information(_Total)\% Processor Performance")?;
        let cpu_utility_counter = add_counter(r"\Processor Information(_Total)\% Processor Utility");
        let gpu_counter = add_counter(r"\GPU Engine(*)\Utilization Percentage");

        Some(PdhMonitor {
            query,
            disk_counter,
            cpu_counter,
            cpu_utility_counter,
            gpu_counter,
            base_mhz: read_base_cpu_mhz(),
            primed: false,
        })
    }
}

/// Lê um valor simples (não-array) de um contador já registrado.
#[cfg(target_os = "windows")]
fn read_pdh_single(counter: isize) -> Option<f64> {
    unsafe {
        let mut value = PdhFmtCounterValue { c_status: 0, _pad: 0, value: 0.0 };
        if PdhGetFormattedCounterValue(counter, PDH_FMT_DOUBLE, std::ptr::null_mut(), &mut value) == 0 {
            Some(value.value)
        } else {
            None
        }
    }
}

/// Lê o contador de GPU, que tem uma instância por processo/engine (ex: uma
/// linha "...engtype_3D" por programa usando a GPU nesse modo). Soma todas as
/// instâncias que são do MESMO tipo de engine e pega o maior total — é
/// exatamente como o Gerenciador de Tarefas calcula o "GPU %" geral.
#[cfg(target_os = "windows")]
fn read_pdh_gpu(counter: isize) -> Option<f64> {
    unsafe {
        let mut buffer_size: u32 = 0;
        let mut buffer_count: u32 = 0;
        let status = PdhGetFormattedCounterArrayW(
            counter,
            PDH_FMT_DOUBLE,
            &mut buffer_size,
            &mut buffer_count,
            std::ptr::null_mut(),
        );
        // PDH_MORE_DATA (0x800007D2) é o retorno esperado dessa primeira
        // chamada — ela só serve pra descobrir o tamanho do buffer necessário.
        if buffer_size == 0 || buffer_count == 0 {
            let _ = status;
            return None;
        }

        let mut raw: Vec<u8> = vec![0u8; buffer_size as usize];
        let status2 = PdhGetFormattedCounterArrayW(
            counter,
            PDH_FMT_DOUBLE,
            &mut buffer_size,
            &mut buffer_count,
            raw.as_mut_ptr() as *mut PdhFmtCounterValueItemW,
        );
        if status2 != 0 {
            return None;
        }

        let items = raw.as_ptr() as *const PdhFmtCounterValueItemW;
        let mut totals: std::collections::HashMap<String, f64> = std::collections::HashMap::new();
        for i in 0..(buffer_count as isize) {
            let item = &*items.offset(i);
            if item.fmt_value.c_status != 0 || item.sz_name.is_null() {
                continue;
            }
            // Lê o nome da instância (string UTF-16 terminada em zero).
            let mut len = 0usize;
            while *item.sz_name.add(len) != 0 && len < 512 {
                len += 1;
            }
            let name_slice = std::slice::from_raw_parts(item.sz_name, len);
            let name = String::from_utf16_lossy(name_slice);
            let engtype = match name.find("engtype_") {
                Some(pos) => name[pos + "engtype_".len()..].to_string(),
                None => continue,
            };
            *totals.entry(engtype).or_insert(0.0) += item.fmt_value.value;
        }
        totals.values().cloned().fold(None, |max, v| match max {
            None => Some(v),
            Some(m) if v > m => Some(v),
            Some(m) => Some(m),
        })
    }
}

/// Faz uma coleta e devolve (gpu%, cpu_mhz, disco_ativo%). Na primeiríssima
/// chamada depois do programa abrir, devolve tudo None (os contadores da PDH
/// precisam de uma leitura "em branco" antes da primeira de verdade). Também
/// devolve tudo None se a PDH nunca conseguiu iniciar nessa máquina.
#[cfg(target_os = "windows")]
fn read_pdh_metrics(
    pdh_opt: &mut Option<PdhMonitor>,
) -> (Option<f64>, Option<f64>, Option<f64>, Option<f64>) {
    let pdh = match pdh_opt.as_mut() {
        Some(p) => p,
        None => return (None, None, None, None),
    };
    unsafe {
        if PdhCollectQueryData(pdh.query) != 0 {
            return (None, None, None, None);
        }
    }
    if !pdh.primed {
        pdh.primed = true;
        return (None, None, None, None);
    }

    let disk_idle = read_pdh_single(pdh.disk_counter);
    let disk_active = disk_idle.map(|idle| 100.0 - idle);

    let cpu_perf = read_pdh_single(pdh.cpu_counter);
    let cpu_mhz = match (cpu_perf, pdh.base_mhz) {
        (Some(perf), Some(base)) => Some(base * perf / 100.0),
        _ => None,
    };

    // "% Processor Utility": o número que o Gerenciador de Tarefas realmente
    // mostra pra CPU (já considera o turbo boost) — pode passar de 100% num
    // core turbinado, por isso limitamos em 100 pra bater com o que a tela
    // do Windows mostra.
    let cpu_utility = pdh
        .cpu_utility_counter
        .and_then(read_pdh_single)
        .map(|v| v.clamp(0.0, 100.0));

    let gpu = pdh.gpu_counter.and_then(read_pdh_gpu);

    (gpu, cpu_mhz, disk_active, cpu_utility)
}

/// Reinício pendente, plano de energia, programas na inicialização e antivírus,
/// numa única chamada de PowerShell (saída em UTF-8 pra não corromper acentos).
#[cfg(target_os = "windows")]
fn check_system_extras_windows() -> Vec<DiagnosticCheck> {
    let ps_cmd = r#"
[Console]::OutputEncoding=[Text.Encoding]::UTF8
$ErrorActionPreference='SilentlyContinue'
$reboot = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') -or (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending')
$plan = (powercfg /getactivescheme) -join ' '
$startup = 0
foreach($k in 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run','HKLM:\Software\Microsoft\Windows\CurrentVersion\Run'){
  $p = Get-ItemProperty $k
  if($p){ $startup += @($p.PSObject.Properties | Where-Object { $_.Name -notlike 'PS*' }).Count }
}
$rt = $null
$mp = Get-MpComputerStatus
if($mp){ $rt = [bool]$mp.RealTimeProtectionEnabled }
[pscustomobject]@{ reboot=[bool]$reboot; plan=$plan; startup=$startup; defender=$rt } | ConvertTo-Json -Compress
"#;
    let mut out = Vec::new();
    let output = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_cmd])
        .creation_flags(CREATE_NO_WINDOW)
        .output();
    let v: serde_json::Value = match output {
        Ok(o) => serde_json::from_str(String::from_utf8_lossy(&o.stdout).trim()).unwrap_or(serde_json::Value::Null),
        Err(_) => serde_json::Value::Null,
    };
    if v.is_null() { return out; }

    let reboot = v["reboot"].as_bool().unwrap_or(false);
    out.push(if reboot {
        DiagnosticCheck{ label: "Reinício pendente".into(), status: "warn".into(), detail: "O Windows está esperando um reinício pra concluir atualizações".into() }
    } else {
        DiagnosticCheck{ label: "Reinício pendente".into(), status: "ok".into(), detail: "Nenhum reinício pendente".into() }
    });

    let plan = v["plan"].as_str().unwrap_or("");
    let plan_name = match (plan.rfind('('), plan.rfind(')')) {
        (Some(a), Some(b)) if b > a => plan[a + 1..b].to_string(),
        _ => "desconhecido".to_string(),
    };
    let lower = plan_name.to_lowercase();
    out.push(if lower.contains("econom") || lower.contains("saver") {
        DiagnosticCheck{ label: "Plano de energia".into(), status: "warn".into(), detail: format!("Plano \"{plan_name}\" ativo — limita o desempenho em jogos") }
    } else {
        DiagnosticCheck{ label: "Plano de energia".into(), status: "ok".into(), detail: format!("Plano \"{plan_name}\" ativo") }
    });

    let startup = v["startup"].as_u64().unwrap_or(0);
    out.push(if startup > 15 {
        DiagnosticCheck{ label: "Programas na inicialização".into(), status: "warn".into(), detail: format!("{startup} programas abrem junto com o Windows — deixa o boot lento") }
    } else {
        DiagnosticCheck{ label: "Programas na inicialização".into(), status: "ok".into(), detail: format!("{startup} programas abrem junto com o Windows") }
    });

    out.push(match v["defender"].as_bool() {
        Some(false) => DiagnosticCheck{ label: "Antivírus".into(), status: "warn".into(), detail: "Proteção em tempo real do Windows Defender está desligada".into() },
        Some(true) => DiagnosticCheck{ label: "Antivírus".into(), status: "ok".into(), detail: "Proteção em tempo real ativa".into() },
        None => DiagnosticCheck{ label: "Antivírus".into(), status: "ok".into(), detail: "Gerenciado por antivírus de terceiros".into() },
    });
    out
}

#[derive(Serialize)]
struct DiagnosticCheck {
    label: String,
    status: String, // "ok" | "warn" | "bad"
    detail: String,
}

#[derive(Serialize)]
struct DiagnosticReport {
    checks: Vec<DiagnosticCheck>,
}

/// Roda uma checagem rápida e real da máquina (sem precisar de UAC, só leitura):
/// espaço em disco, saúde física dos discos (S.M.A.R.T.), dispositivos com erro
/// no Gerenciador de Dispositivos, e erros críticos recentes no Log de Eventos.
/// Não roda SFC/DISM aqui de propósito — isso demora minutos e travaria o clique.
#[tauri::command]
async fn run_diagnostics(state: State<'_, SysState>) -> Result<DiagnosticReport, String> {
    let (cpu_percent, ram_percent) = {
        let mut sys = state.0.lock().unwrap();
        sys.refresh_cpu_usage();
        sys.refresh_memory();
        let cpu = sys.global_cpu_usage() as f64;
        let total = sys.total_memory() as f64;
        let used = sys.used_memory() as f64;
        let ram = if total > 0.0 { (used / total) * 100.0 } else { 0.0 };
        (cpu, ram)
    };

    let mut checks = Vec::new();

    // Carga atual (só alerta se estiver realmente alta — número solto não ajuda)
    let load_detail = format!("CPU {:.0}% · RAM {:.0}% agora", cpu_percent, ram_percent);
    checks.push(if cpu_percent >= 90.0 || ram_percent >= 90.0 {
        DiagnosticCheck{ label: "Carga do sistema".into(), status: "bad".into(), detail: format!("{load_detail} — algo está pesando demais no PC") }
    } else if cpu_percent >= 75.0 || ram_percent >= 85.0 {
        DiagnosticCheck{ label: "Carga do sistema".into(), status: "warn".into(), detail: format!("{load_detail} — carga alta") }
    } else {
        DiagnosticCheck{ label: "Carga do sistema".into(), status: "ok".into(), detail: format!("{load_detail} — tranquilo") }
    });

    // Tempo ligado sem reiniciar
    let up = System::uptime();
    let days = up / 86400;
    let hours = (up % 86400) / 3600;
    checks.push(if days >= 7 {
        DiagnosticCheck{ label: "Tempo ligado".into(), status: "warn".into(), detail: format!("Ligado há {days} dias — reiniciar libera memória e aplica atualizações pendentes") }
    } else {
        DiagnosticCheck{ label: "Tempo ligado".into(), status: "ok".into(), detail: if days > 0 { format!("Ligado há {days}d {hours}h") } else { format!("Ligado há {hours}h") } }
    });

    // Espaço por disco, com valores reais em GB
    let disks_list = Disks::new_with_refreshed_list();
    for d in disks_list.iter() {
        let total = d.total_space() as f64;
        let avail = d.available_space() as f64;
        if total <= 0.0 { continue; }
        let free_pct = (avail / total) * 100.0;
        let name = d.mount_point().to_string_lossy().to_string();
        let detail = format!("{:.0} GB livres de {:.0} GB ({:.0}% livre)", avail / 1_073_741_824.0, total / 1_073_741_824.0, free_pct);
        let status = if free_pct < 5.0 { "bad" } else if free_pct < 12.0 { "warn" } else { "ok" };
        checks.push(DiagnosticCheck{ label: format!("Espaço em {name}"), status: status.into(), detail });
    }

    // Checagens específicas do Windows
    checks.extend(check_devices_windows());

    let (disk_status, disk_detail) = check_disk_health_windows();
    checks.push(DiagnosticCheck{ label: "Saúde física dos discos".into(), status: disk_status, detail: disk_detail });

    let (evt_status, evt_detail) = check_recent_critical_events_windows();
    checks.push(DiagnosticCheck{ label: "Erros do sistema (24h)".into(), status: evt_status, detail: evt_detail });

    #[cfg(target_os = "windows")]
    {
        let extra = tauri::async_runtime::spawn_blocking(check_system_extras_windows)
            .await
            .unwrap_or_default();
        checks.extend(extra);
    }

    Ok(DiagnosticReport{ checks })
}

/// Analisa um jogo específico (pelo caminho do .exe): confere se os ajustes de
/// performance já foram aplicados pra ele, se tem espaço livre suficiente no disco
/// onde ele está instalado, o uso atual de CPU/RAM da máquina, e lista os apps mais
/// pesados rodando agora que podem estar competindo por recurso.
/// Não estima "tantos % de FPS a mais" — isso exigiria rodar o jogo com benchmark
/// de verdade, o que este app não faz. O que dá pra afirmar com dado real é isto aqui.
#[tauri::command]
async fn analyze_game(state: State<'_, SysState>, exe_path: String) -> Result<DiagnosticReport, String> {
    let mut checks = Vec::new();
    let exe_name = exe_path.split(['\\', '/']).last().unwrap_or(&exe_path).to_string();

    let (cpu_percent, ram_percent, running, heavy_procs) = {
        let mut sys = state.0.lock().unwrap();
        sys.refresh_cpu_usage();
        sys.refresh_memory();
        sys.refresh_processes(ProcessesToUpdate::All, true);
        let cpu = sys.global_cpu_usage() as f64;
        let total = sys.total_memory() as f64;
        let used = sys.used_memory() as f64;
        let ram = if total > 0.0 { (used / total) * 100.0 } else { 0.0 };

        let running = sys.processes().values().any(|p| {
            p.name().to_string_lossy().eq_ignore_ascii_case(&exe_name)
        });

        // apps pesados (>400MB) rodando agora, exceto o próprio jogo e processos do sistema/app
        let ignore_names = ["fluxtweakers", "system", "registry", "memory compression", &exe_name.to_lowercase()];
        let mut grouped: std::collections::HashMap<String, f64> = std::collections::HashMap::new();
        for p in sys.processes().values() {
            let name = p.name().to_string_lossy().to_string();
            if ignore_names.iter().any(|i| name.to_lowercase().contains(i)) { continue; }
            *grouped.entry(name).or_insert(0.0) += p.memory() as f64 / 1_048_576.0;
        }
        let mut heavy: Vec<(String, f64)> = grouped.into_iter().filter(|(_, mb)| *mb > 400.0).collect();
        heavy.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        heavy.truncate(3);
        (cpu, ram, running, heavy)
    };

    checks.push(DiagnosticCheck{
        label: "Status agora".into(),
        status: "ok".into(),
        detail: if running { format!("{exe_name} está rodando neste momento") } else { format!("{exe_name} não está aberto agora — os números de CPU/RAM abaixo são da máquina em geral, não do jogo") },
    });

    // espaço livre no disco onde o jogo está instalado
    let drive_prefix: String = exe_path.chars().take(3).collect();
    let disks_list = Disks::new_with_refreshed_list();
    if let Some(disk) = disks_list.iter().find(|d| {
        d.mount_point().to_string_lossy().to_uppercase().starts_with(&drive_prefix.to_uppercase())
    }) {
        let total = disk.total_space() as f64;
        let avail = disk.available_space() as f64;
        let free_gb = avail / 1_073_741_824.0;
        let free_pct = if total > 0.0 { (avail / total) * 100.0 } else { 0.0 };
        checks.push(if free_pct < 8.0 {
            DiagnosticCheck{ label: "Espaço em disco".into(), status: "bad".into(), detail: format!("Só {:.0} GB livres no disco do jogo ({:.0}%) — isso pode causar engasgos de streaming de textura", free_gb, free_pct) }
        } else if free_pct < 15.0 {
            DiagnosticCheck{ label: "Espaço em disco".into(), status: "warn".into(), detail: format!("{:.0} GB livres no disco do jogo ({:.0}%) — vale liberar espaço", free_gb, free_pct) }
        } else {
            DiagnosticCheck{ label: "Espaço em disco".into(), status: "ok".into(), detail: format!("{:.0} GB livres no disco do jogo", free_gb) }
        });
    }

    // tweaks de performance já aplicados pra esse exe especificamente
    let (cpu_pri_status, cpu_pri_detail) = check_game_cpu_priority_windows(&exe_name);
    checks.push(DiagnosticCheck{ label: "Prioridade de CPU".into(), status: cpu_pri_status, detail: cpu_pri_detail });

    let (gpu_pref_status, gpu_pref_detail) = check_game_gpu_preference_windows(&exe_path);
    checks.push(DiagnosticCheck{ label: "Preferência de GPU".into(), status: gpu_pref_status, detail: gpu_pref_detail });

    let (fso_status, fso_detail) = check_game_fso_windows(&exe_path);
    checks.push(DiagnosticCheck{ label: "Otimizações de tela cheia".into(), status: fso_status, detail: fso_detail });

    // uso atual de CPU/RAM da máquina
    checks.push(if cpu_percent >= 85.0 {
        DiagnosticCheck{ label: "CPU disponível agora".into(), status: "warn".into(), detail: format!("CPU já em {:.0}% de uso — pouca folga sobrando pro jogo", cpu_percent) }
    } else {
        DiagnosticCheck{ label: "CPU disponível agora".into(), status: "ok".into(), detail: format!("CPU em {:.0}%, com folga", cpu_percent) }
    });
    checks.push(if ram_percent >= 85.0 {
        DiagnosticCheck{ label: "RAM disponível agora".into(), status: "warn".into(), detail: format!("RAM já em {:.0}% de uso — pode faltar memória durante o jogo", ram_percent) }
    } else {
        DiagnosticCheck{ label: "RAM disponível agora".into(), status: "ok".into(), detail: format!("RAM em {:.0}%, com folga", ram_percent) }
    });

    if !heavy_procs.is_empty() {
        let list = heavy_procs.iter().map(|(n, mb)| format!("{n} ({:.0} MB)", mb)).collect::<Vec<_>>().join(", ");
        checks.push(DiagnosticCheck{ label: "Apps pesados rodando agora".into(), status: "warn".into(), detail: format!("{list} — feche o que não precisar antes de jogar") });
    } else {
        checks.push(DiagnosticCheck{ label: "Apps pesados rodando agora".into(), status: "ok".into(), detail: "Nada consumindo memória pesado em segundo plano".into() });
    }

    Ok(DiagnosticReport{ checks })
}

#[cfg(target_os = "windows")]
fn check_game_cpu_priority_windows(exe_name: &str) -> (String, String) {
    let key = format!(r"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\{exe_name}\PerfOptions");
    match reg_query_value(&key, "CpuPriorityClass") {
        Some(v) if v.trim() == "0x3" => ("ok".to_string(), "Prioridade Alta já configurada pra esse jogo".to_string()),
        _ => ("warn".to_string(), "Prioridade padrão (Normal) — use o preset Desempenho na aba Meus Jogos pra subir".to_string()),
    }
}
#[cfg(target_os = "windows")]
fn check_game_gpu_preference_windows(exe_path: &str) -> (String, String) {
    match reg_query_value(r"HKCU\Software\Microsoft\DirectX\UserGpuPreference", exe_path) {
        Some(v) if v.contains("GpuPreference=2") => ("ok".to_string(), "Já configurado pra usar a GPU dedicada/de alto desempenho".to_string()),
        _ => ("warn".to_string(), "Ainda no automático — use o preset Desempenho na aba Meus Jogos pra forçar a GPU dedicada".to_string()),
    }
}
#[cfg(target_os = "windows")]
fn check_game_fso_windows(exe_path: &str) -> (String, String) {
    let key = r"HKCU\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers";
    match reg_query_value(key, exe_path) {
        Some(v) if v.contains("DISABLEDXMAXIMIZEDWINDOWEDMODE") => ("ok".to_string(), "Otimizações de tela cheia já desativadas (reduz latência)".to_string()),
        _ => ("warn".to_string(), "Otimizações de tela cheia do Windows ainda ativas — o preset Desempenho desativa isso".to_string()),
    }
}
#[cfg(not(target_os = "windows"))]
fn check_game_cpu_priority_windows(_exe_name: &str) -> (String, String) { ("ok".to_string(), "Checagem disponível apenas no Windows".to_string()) }
#[cfg(not(target_os = "windows"))]
fn check_game_gpu_preference_windows(_exe_path: &str) -> (String, String) { ("ok".to_string(), "Checagem disponível apenas no Windows".to_string()) }
#[cfg(not(target_os = "windows"))]
fn check_game_fso_windows(_exe_path: &str) -> (String, String) { ("ok".to_string(), "Checagem disponível apenas no Windows".to_string()) }

/// Dispositivos com problema. O Windows usa o mesmo "código de erro" pra falha
/// real (ex: 43, 28) e pra dispositivo DESATIVADO de propósito (código 22) —
/// por isso a checagem separa os dois. Desativar o HPET ("Timer de eventos de
/// alta precisão") é um truque comum pra ganhar FPS, não um defeito.
#[cfg(target_os = "windows")]
fn check_devices_windows() -> Vec<DiagnosticCheck> {
    // Saída em UTF-8 (senão nomes com acento vêm corrompidos).
    let ps_cmd = r#"
[Console]::OutputEncoding=[Text.Encoding]::UTF8
Get-PnpDevice -PresentOnly -ErrorAction SilentlyContinue | Where-Object { $_.ConfigManagerErrorCode -ne 0 } | ForEach-Object {
  $n = if ($_.FriendlyName) { $_.FriendlyName } else { $_.InstanceId }
  "$($_.ConfigManagerErrorCode)|$n"
}
"#;
    let output = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_cmd])
        .creation_flags(CREATE_NO_WINDOW)
        .output();
    let text = match output {
        Ok(o) => String::from_utf8_lossy(&o.stdout).to_string(),
        Err(_) => {
            return vec![DiagnosticCheck{
                label: "Dispositivos (drivers)".into(), status: "warn".into(),
                detail: "Não foi possível checar (permissão ou PowerShell indisponível)".into(),
            }];
        }
    };

    let mut errors: Vec<String> = Vec::new();
    let mut disabled: Vec<String> = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        let Some((code, name)) = line.split_once('|') else { continue };
        let code: u32 = code.trim().parse().unwrap_or(0);
        let name = name.trim().to_string();
        if name.is_empty() { continue; }
        match code {
            0 | 24 | 45 => {}                       // ok / não presente / desconectado
            22 => disabled.push(name),              // desativado manualmente
            _ => errors.push(format!("{name} (cód. {code})")),
        }
    }

    let mut out = Vec::new();
    if errors.is_empty() {
        out.push(DiagnosticCheck{
            label: "Dispositivos (drivers)".into(), status: "ok".into(),
            detail: "Nenhum dispositivo com erro de driver".into(),
        });
    } else {
        out.push(DiagnosticCheck{
            label: "Dispositivos (drivers)".into(), status: "bad".into(),
            detail: format!("{} com erro de driver||{}", errors.len(), errors.join("||")),
        });
    }
    if !disabled.is_empty() {
        let hpet = disabled.iter().any(|n| {
            let l = n.to_lowercase();
            l.contains("alta precis") || l.contains("high precision")
        });
        let head = if hpet {
            "Desativados manualmente — normal em PC otimizado (o HPET, por exemplo, muita gente desliga pra ganhar FPS)"
        } else {
            "Desativados manualmente — não é erro"
        };
        out.push(DiagnosticCheck{
            label: "Dispositivos desativados".into(), status: "ok".into(),
            detail: format!("{head}||{}", disabled.join("||")),
        });
    }
    out
}

#[cfg(target_os = "windows")]
fn check_disk_health_windows() -> (String, String) {
    let ps_cmd = "[Console]::OutputEncoding=[Text.Encoding]::UTF8; (Get-PhysicalDisk -ErrorAction SilentlyContinue | Where-Object { $_.HealthStatus -ne 'Healthy' }).FriendlyName -join ', '";
    let output = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_cmd])
        .creation_flags(CREATE_NO_WINDOW)
        .output();
    match output {
        Ok(o) => {
            let text = String::from_utf8_lossy(&o.stdout).trim().to_string();
            if text.is_empty() {
                ("ok".to_string(), "Todos os discos reportam saúde OK (S.M.A.R.T.)".to_string())
            } else {
                ("bad".to_string(), format!("Discos com alerta de saúde: {text}"))
            }
        }
        Err(_) => ("warn".to_string(), "Não foi possível checar a saúde dos discos".to_string()),
    }
}

#[cfg(target_os = "windows")]
fn check_recent_critical_events_windows() -> (String, String) {
    let ps_cmd = r#"
[Console]::OutputEncoding=[Text.Encoding]::UTF8
$e = Get-WinEvent -FilterHashtable @{LogName='System'; Level=1,2; StartTime=(Get-Date).AddHours(-24)} -ErrorAction SilentlyContinue
if ($e) { $e | Group-Object ProviderName | Sort-Object Count -Descending | Select-Object -First 4 | ForEach-Object { "$($_.Count)|$($_.Name)" } }
"#;
    let output = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_cmd])
        .creation_flags(CREATE_NO_WINDOW)
        .output();
    match output {
        Ok(o) => {
            let text = String::from_utf8_lossy(&o.stdout).to_string();
            let mut total: u64 = 0;
            let mut sources: Vec<String> = Vec::new();
            let mut hardware = false;
            for line in text.lines() {
                let Some((n, name)) = line.trim().split_once('|') else { continue };
                let n: u64 = n.trim().parse().unwrap_or(0);
                if n == 0 { continue; }
                total += n;
                let short = name.trim().trim_start_matches("Microsoft-Windows-").to_string();
                let l = short.to_lowercase();
                if l.contains("disk") || l.contains("ntfs") || l.contains("volmgr") || l.contains("whea") || l.contains("stornvme") {
                    hardware = true;
                }
                sources.push(format!("{short} ({n})"));
            }
            let list = if sources.is_empty() { String::new() } else { format!("||{}", sources.join("||")) };
            if total == 0 {
                ("ok".to_string(), "Nenhum erro no log do sistema nas últimas 24h".to_string())
            } else if total >= 30 {
                ("bad".to_string(), format!("{total} erros nas últimas 24h — vale investigar{list}"))
            } else if total >= 10 || hardware {
                ("warn".to_string(), format!("{total} erros nas últimas 24h{list}"))
            } else {
                ("ok".to_string(), format!("{total} erros leves nas últimas 24h (normal, nada crítico){list}"))
            }
        }
        Err(_) => ("warn".to_string(), "Não foi possível checar o Log de Eventos".to_string()),
    }
}

#[cfg(not(target_os = "windows"))]
fn check_devices_windows() -> Vec<DiagnosticCheck> {
    vec![DiagnosticCheck{ label: "Dispositivos (drivers)".into(), status: "ok".into(), detail: "Checagem disponível apenas no Windows".into() }]
}
#[cfg(not(target_os = "windows"))]
fn check_disk_health_windows() -> (String, String) {
    ("ok".to_string(), "Checagem disponível apenas no Windows".to_string())
}
#[cfg(not(target_os = "windows"))]
fn check_recent_critical_events_windows() -> (String, String) {
    ("ok".to_string(), "Checagem disponível apenas no Windows".to_string())
}

#[cfg(target_os = "windows")]
fn read_cache_bytes_windows() -> f64 {
    // Mesmo contador que o Gerenciador de Tarefas usa pra mostrar "Em cache" —
    // é isso que realmente cai quando a limpeza de Standby List roda de verdade.
    // IMPORTANTE: usa WMI (Win32_PerfFormattedData_PerfOS_Memory) em vez de
    // Get-Counter com nome em inglês — o Get-Counter só reconhece o nome
    // LOCALIZADO do contador (em Windows em português, "\Memory\Cache Bytes"
    // não existe com esse nome) e falhava silenciosamente, sempre voltando
    // zero. As propriedades WMI são sempre em inglês, não importa o idioma
    // do Windows instalado.
    let ps_cmd = "(Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory -ErrorAction SilentlyContinue).CacheBytes";

    let output = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_cmd])
        .creation_flags(CREATE_NO_WINDOW)
        .output();

    match output {
        Ok(o) => {
            let text = String::from_utf8_lossy(&o.stdout);
            text.trim().replace(',', ".").parse().unwrap_or(0.0)
        }
        Err(_) => 0.0,
    }
}

#[cfg(not(target_os = "windows"))]
fn read_cache_bytes_windows() -> f64 {
    0.0
}

#[derive(Serialize)]
struct DeepScanResult {
    status: String,  // "ok" | "fixed" | "unfixable" | "error"
    summary: String,
    raw_tail: String,
}

/// Roda sfc /scannow + DISM /ScanHealth de verdade, elevado (pede UAC), e espera
/// terminar pra ler o resultado real de um arquivo temporário — diferente do
/// run_bat_script (que é fire-and-forget), aqui a gente PRECISA do resultado.
/// Isso demora vários minutos de propósito (é o Windows verificando arquivo por
/// arquivo do sistema), então só deve ser chamado quando o usuário pedir
/// explicitamente uma verificação profunda, não no "Analisar Sistema" rápido.
#[cfg(target_os = "windows")]
#[tauri::command]
async fn run_deep_scan() -> Result<DeepScanResult, String> {
    let temp_dir = std::env::temp_dir();
    let out_path = temp_dir.join(format!("dgeras-scan-{}.log", uuid_like()));
    let bat_path = temp_dir.join(format!("dgeras-scan-{}.bat", uuid_like()));

    let script = format!(
        "@echo off\r\nchcp 65001 >nul\r\necho ===SFC=== > \"{out}\"\r\nsfc /scannow >> \"{out}\" 2>&1\r\necho ===DISM=== >> \"{out}\"\r\nDISM /Online /Cleanup-Image /ScanHealth >> \"{out}\" 2>&1\r\necho ===FIM===>> \"{out}\"\r\n",
        out = out_path.to_string_lossy()
    );
    fs::write(&bat_path, script).map_err(|e| format!("Falha ao preparar a verificação: {e}"))?;

    let ps_launcher = format!(
        "$p = Start-Process -FilePath 'cmd.exe' -ArgumentList '/c \"{path}\"' -Verb RunAs -WindowStyle Hidden -Wait -PassThru; exit $p.ExitCode",
        path = bat_path.to_string_lossy().replace('\'', "''")
    );

    // sfc/DISM podem levar minutos — isso BLOQUEIA a thread até terminar, então roda
    // numa thread dedicada (spawn_blocking) pra não travar o runtime assíncrono do
    // Tauri, que é o mesmo canal usado pra entregar a resposta de volta pro app.
    // Sem isso, o app fica preso em "Verificando..." pra sempre mesmo quando o
    // Windows já terminou (a resposta nunca consegue "voltar" pra tela).
    let ps_launcher_owned = ps_launcher.clone();
    let output = tokio::task::spawn_blocking(move || {
        Command::new("powershell")
            .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps_launcher_owned])
            .creation_flags(CREATE_NO_WINDOW)
            .output()
    })
    .await
    .map_err(|e| format!("Falha interna ao rodar a verificação: {e}"))?;

    let _ = fs::remove_file(&bat_path);

    match output {
        Ok(out) => {
            let content = fs::read_to_string(&out_path).unwrap_or_default();
            let _ = fs::remove_file(&out_path);
            if content.trim().is_empty() {
                // código 1223 = "operação cancelada pelo usuário" (UAC negado/fechado)
                let stderr = String::from_utf8_lossy(&out.stderr);
                let cancelled = out.status.code() == Some(1223) || stderr.contains("1223") || stderr.to_lowercase().contains("cancel");
                let msg = if cancelled {
                    "A janela de permissão de administrador (UAC) foi cancelada ou fechada, então a verificação não rodou. Clique em 'Rodar verificação profissional' de novo e aceite a permissão."
                } else {
                    "Não consegui ler o resultado da verificação. Pode tentar de novo — se continuar assim, algum antivírus pode estar bloqueando."
                };
                return Ok(DeepScanResult{ status: "error".into(), summary: msg.into(), raw_tail: stderr.trim().to_string() });
            }
            Ok(parse_sfc_result(&content))
        }
        Err(e) => Err(format!("Falha ao rodar a verificação: {e}")),
    }
}

#[cfg(target_os = "windows")]
fn parse_sfc_result(content: &str) -> DeepScanResult {
    let lower = content.to_lowercase();
    let (status, summary) = if lower.contains("não encontrou nenhuma violação") || lower.contains("did not find any integrity violations") {
        ("ok", "Nenhum arquivo de sistema corrompido encontrado. Tudo íntegro.")
    } else if lower.contains("encontrou arquivos corrompidos e") && (lower.contains("reparou") || lower.contains("êxito")) || lower.contains("successfully repaired") {
        ("fixed", "Encontrou arquivos de sistema corrompidos e conseguiu reparar todos automaticamente.")
    } else if lower.contains("não foi possível corrigir") || lower.contains("unable to fix") {
        ("unfixable", "Encontrou arquivos corrompidos mas não conseguiu corrigir todos — pode indicar um problema mais sério no disco ou instalação do Windows.")
    } else if lower.contains("não pôde executar") || lower.contains("could not perform") {
        ("error", "O Windows não conseguiu completar a verificação (geralmente precisa rodar em Modo de Segurança ou verificar o disco antes).")
    } else {
        ("error", "Verificação concluída, mas não consegui interpretar automaticamente o resultado — veja o texto bruto abaixo.")
    };
    // guarda as últimas linhas não-vazias como evidência bruta, sem exagerar no tamanho
    let tail: Vec<&str> = content.lines().filter(|l| !l.trim().is_empty()).collect();
    let raw_tail = tail.iter().rev().take(12).rev().cloned().collect::<Vec<_>>().join("\n");
    DeepScanResult{ status: status.to_string(), summary: summary.to_string(), raw_tail }
}

#[cfg(not(target_os = "windows"))]
#[tauri::command]
async fn run_deep_scan() -> Result<DeepScanResult, String> {
    Ok(DeepScanResult{ status: "error".into(), summary: "Disponível só no Windows".into(), raw_tail: String::new() })
}

/// Recebe o texto do .bat gerado pelo painel, salva num arquivo temporário
/// e executa TOTALMENTE ESCONDIDO (sem console piscando, sem downloads).
/// O único aviso que aparece pro usuário é o próprio UAC do Windows pedindo
/// permissão de administrador — isso o sistema operacional exige e não dá
/// pra pular, mas fora isso roda tudo em segundo plano dentro do app.
#[tauri::command]
fn run_bat_script(script_text: String) -> Result<String, String> {
    let temp_dir = std::env::temp_dir();
    let file_name = format!("dgeras-run-{}.bat", uuid_like());
    let file_path = temp_dir.join(&file_name);

    fs::write(&file_path, script_text).map_err(|e| format!("Falha ao gravar script: {e}"))?;

    let path_str = file_path.to_string_lossy().to_string();

    // Usa o PowerShell só como "lançador" elevado: Start-Process com -Verb RunAs
    // dispara o UAC, e -WindowStyle Hidden garante que nenhuma janela de console
    // apareça enquanto o .bat roda por trás. -Wait espera o script terminar.
    let ps_launcher = format!(
        "Start-Process -FilePath 'cmd.exe' -ArgumentList '/c \"{path}\"' -Verb RunAs -WindowStyle Hidden -Wait",
        path = path_str.replace('\'', "''")
    );

    #[cfg(target_os = "windows")]
    let result = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps_launcher])
        .creation_flags(CREATE_NO_WINDOW)
        .spawn();

    #[cfg(not(target_os = "windows"))]
    let result = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps_launcher])
        .spawn();

    match result {
        Ok(_) => Ok("Ajustes aplicados com sucesso".to_string()),
        Err(e) => Err(format!("Falha ao executar script: {e}")),
    }
}

fn uuid_like() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    format!("{nanos:x}")
}

// ===== Limpeza de RAM (mesma técnica do ISLC / RAMMap) — REESCRITA DO ZERO =====
//
// O Windows guarda na "Standby List" partes de memória que já foram usadas
// mas não estão mais ativas — ele mantém isso em cache achando que você pode
// precisar de novo. A limpeza chama a mesma função interna do Windows
// (NtSetSystemInformation) que o Gerenciador de Tarefas e ferramentas como
// RAMMap usam.
//
// Isso PRECISA de admin. Pra não pedir senha toda vez, a gente cria uma
// Tarefa Agendada do Windows UMA VEZ (pede UAC só nessa primeira vez),
// configurada com "privilégios mais altos", que roda o PRÓPRIO executável
// do FluxTweakers num modo "worker" invisível (--ram-clean-worker) — SEM
// PowerShell, SEM script gerado em disco, SEM Add-Type/compilação de C# em
// tempo de execução. Isso elimina de vez as causas dos timeouts inconsistentes
// (antivírus rescaneando um script que muda a cada clique, tempo de start do
// PowerShell, compilação just-in-time do .NET).

const RAM_CLEAN_TASK_NAME: &str = "FluxTweakersRamClean";
const RAM_WORKER_FLAG: &str = "--ram-clean-worker";

#[cfg(target_os = "windows")]
#[link(name = "kernel32")]
extern "system" {
    fn GetCurrentProcess() -> isize;
    fn CloseHandle(h: isize) -> i32;
    fn GlobalMemoryStatusEx(buf: *mut MemoryStatusEx) -> i32;
    fn LoadLibraryW(name: *const u16) -> isize;
    fn GetProcAddress(module: isize, name: *const u8) -> *const ();
    fn K32EnumProcesses(pids: *mut u32, cb: u32, cb_needed: *mut u32) -> i32;
    fn OpenProcess(access: u32, inherit: i32, pid: u32) -> isize;
    fn K32EmptyWorkingSet(h: isize) -> i32;
}

#[cfg(target_os = "windows")]
#[link(name = "advapi32")]
extern "system" {
    fn OpenProcessToken(h: isize, access: u32, out_token: *mut isize) -> i32;
    fn LookupPrivilegeValueW(system_name: *const u16, name: *const u16, luid: *mut Luid) -> i32;
    fn AdjustTokenPrivileges(
        token: isize,
        disable_all: i32,
        new_state: *mut TokenPrivileges,
        buffer_len: u32,
        prev_state: *mut (),
        return_len: *mut u32,
    ) -> i32;
    fn RegGetValueW(
        hkey: isize,
        sub_key: *const u16,
        value: *const u16,
        flags: u32,
        type_out: *mut u32,
        data: *mut core::ffi::c_void,
        data_len: *mut u32,
    ) -> i32;
}

#[cfg(target_os = "windows")]
#[repr(C)]
struct MemoryStatusEx {
    dw_length: u32,
    dw_memory_load: u32,
    ull_total_phys: u64,
    ull_avail_phys: u64,
    ull_total_page_file: u64,
    ull_avail_page_file: u64,
    ull_total_virtual: u64,
    ull_avail_virtual: u64,
    ull_avail_extended_virtual: u64,
}

#[cfg(target_os = "windows")]
#[repr(C)]
struct Luid {
    low_part: u32,
    high_part: i32,
}

#[cfg(target_os = "windows")]
#[repr(C)]
struct LuidAndAttributes {
    luid: Luid,
    attributes: u32,
}

#[cfg(target_os = "windows")]
#[repr(C)]
struct TokenPrivileges {
    privilege_count: u32,
    privileges: LuidAndAttributes,
}

#[cfg(target_os = "windows")]
fn available_phys_mb() -> u64 {
    unsafe {
        let mut mem = MemoryStatusEx {
            dw_length: std::mem::size_of::<MemoryStatusEx>() as u32,
            dw_memory_load: 0,
            ull_total_phys: 0,
            ull_avail_phys: 0,
            ull_total_page_file: 0,
            ull_avail_page_file: 0,
            ull_total_virtual: 0,
            ull_avail_virtual: 0,
            ull_avail_extended_virtual: 0,
        };
        if GlobalMemoryStatusEx(&mut mem) != 0 {
            mem.ull_avail_phys / 1024 / 1024
        } else {
            0
        }
    }
}

/// "Reduzir em uso": manda o Windows tirar da memória física tudo que cada
/// processo não está usando ativamente agora (igual o Gerenciador de Tarefas
/// faz internamente), sem matar nada — seguro e reversível na hora.
#[cfg(target_os = "windows")]
fn trim_all_working_sets() -> u32 {
    let mut trimmed = 0u32;
    unsafe {
        let mut pids = vec![0u32; 4096];
        let mut bytes_needed = 0u32;
        if K32EnumProcesses(pids.as_mut_ptr(), (pids.len() * 4) as u32, &mut bytes_needed) == 0 {
            return 0;
        }
        let count = ((bytes_needed as usize) / 4).min(pids.len());
        const PROCESS_SET_QUOTA: u32 = 0x0100;
        const PROCESS_QUERY_INFORMATION: u32 = 0x0400;
        for pid in pids.iter().take(count).copied() {
            if pid == 0 {
                continue;
            }
            let h = OpenProcess(PROCESS_SET_QUOTA | PROCESS_QUERY_INFORMATION, 0, pid);
            if h == 0 {
                continue;
            }
            if K32EmptyWorkingSet(h) != 0 {
                trimmed += 1;
            }
            CloseHandle(h);
        }
    }
    trimmed
}

/// "Limpar cache": purga a Standby List inteira via uma API não documentada
/// do Windows (NtSetSystemInformation). Precisa habilitar antes o privilégio
/// SeProfileSingleProcessPrivilege no token do processo — se o Windows negar
/// (STATUS_PRIVILEGE_NOT_HELD, algo que acontece em algumas máquinas mesmo
/// sendo admin, fora do nosso controle), cai automático pro "Reduzir em uso"
#[cfg(target_os = "windows")]
#[repr(C)]
struct SystemMemoryListInfo {
    zero_page_count: usize,
    free_page_count: usize,
    modified_page_count: usize,
    modified_no_write_page_count: usize,
    bad_page_count: usize,
    page_count_by_priority: [usize; 8],
    repurposed_pages_by_priority: [usize; 8],
    modified_page_count_page_file: usize,
}

/// Carrega uma função da ntdll dinamicamente (LoadLibrary + GetProcAddress —
/// ela não tem import-lib no SDK do Windows pra linkar estaticamente).
#[cfg(target_os = "windows")]
unsafe fn load_ntdll_proc(name: &[u8]) -> Option<*const ()> {
    let ntdll_name: Vec<u16> = "ntdll.dll\0".encode_utf16().collect();
    let ntdll = LoadLibraryW(ntdll_name.as_ptr());
    if ntdll == 0 {
        return None;
    }
    let addr = GetProcAddress(ntdll, name.as_ptr());
    if addr.is_null() {
        None
    } else {
        Some(addr)
    }
}

/// Lê o tamanho REAL da Standby List agora (a mesma informação que o
/// Gerenciador de Tarefas mostra como "Em cache" e o RAMMap mostra como
/// "Standby") — usando NtQuerySystemInformation, sem WMI. É isso que
/// permite reportar corretamente quantos GB foram liberados numa limpeza,
/// já que "memória disponível" no Windows já conta a standby list como
/// disponível mesmo ANTES de limpar (por isso aquele número quase não se
/// move, mesmo numa limpeza real de vários GB).
#[cfg(target_os = "windows")]
fn standby_list_mb() -> Option<u64> {
    unsafe {
        let proc_addr = load_ntdll_proc(b"NtQuerySystemInformation\0")?;
        let nt_query_system_information: extern "system" fn(
            i32,
            *mut SystemMemoryListInfo,
            u32,
            *mut u32,
        ) -> i32 = std::mem::transmute(proc_addr);

        const SYSTEM_MEMORY_LIST_INFORMATION: i32 = 80;
        let mut info = SystemMemoryListInfo {
            zero_page_count: 0,
            free_page_count: 0,
            modified_page_count: 0,
            modified_no_write_page_count: 0,
            bad_page_count: 0,
            page_count_by_priority: [0; 8],
            repurposed_pages_by_priority: [0; 8],
            modified_page_count_page_file: 0,
        };
        let mut return_len: u32 = 0;
        let status = nt_query_system_information(
            SYSTEM_MEMORY_LIST_INFORMATION,
            &mut info,
            std::mem::size_of::<SystemMemoryListInfo>() as u32,
            &mut return_len,
        );
        if status != 0 {
            return None;
        }
        let standby_pages: u64 = info.page_count_by_priority.iter().map(|&p| p as u64).sum();
        Some(standby_pages * 4096 / 1024 / 1024)
    }
}

/// em vez de mostrar erro pro usuário.
#[cfg(target_os = "windows")]
fn purge_standby_list() -> Result<u32, String> {
    unsafe {
        const TOKEN_ADJUST_PRIVILEGES: u32 = 0x20;
        const TOKEN_QUERY: u32 = 0x8;
        let mut h_token: isize = 0;
        if OpenProcessToken(
            GetCurrentProcess(),
            TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY,
            &mut h_token,
        ) == 0
        {
            return Err("Não consegui abrir o token do processo".to_string());
        }

        let name_wide: Vec<u16> = "SeProfileSingleProcessPrivilege\0".encode_utf16().collect();
        let mut luid = Luid { low_part: 0, high_part: 0 };
        LookupPrivilegeValueW(std::ptr::null(), name_wide.as_ptr(), &mut luid);

        let mut priv_struct = TokenPrivileges {
            privilege_count: 1,
            privileges: LuidAndAttributes { luid, attributes: 0x2 },
        };
        AdjustTokenPrivileges(
            h_token,
            0,
            &mut priv_struct,
            0,
            std::ptr::null_mut(),
            std::ptr::null_mut(),
        );
        CloseHandle(h_token);

        let proc_addr = match load_ntdll_proc(b"NtSetSystemInformation\0") {
            Some(a) => a,
            None => return Err("NtSetSystemInformation não encontrado".to_string()),
        };
        let nt_set_system_information: extern "system" fn(i32, *mut i32, u32) -> i32 =
            std::mem::transmute(proc_addr);

        const SYSTEM_MEMORY_LIST_INFORMATION: i32 = 80;
        const MEMORY_PURGE_STANDBY_LIST: i32 = 4;
        let mut command = MEMORY_PURGE_STANDBY_LIST;
        let status = nt_set_system_information(SYSTEM_MEMORY_LIST_INFORMATION, &mut command, 4);

        if status == -1073741727i32 {
            // STATUS_PRIVILEGE_NOT_HELD: sem esse privilégio nessa máquina —
            // cai pro modo working-set em vez de falhar pro usuário.
            Ok(trim_all_working_sets())
        } else if status != 0 {
            Err(format!("NtSetSystemInformation retornou status={status}"))
        } else {
            Ok(0)
        }
    }
}

/// Roda de verdade a limpeza — chamado dentro do processo elevado disparado
/// pela Tarefa Agendada (o próprio FluxTweakers.exe relançado com
/// --ram-clean-worker) — e grava o resultado no arquivo que o app principal
/// (não-elevado) está esperando. Não abre janela nenhuma.
#[cfg(target_os = "windows")]
fn ram_clean_worker_entrypoint() {
    let dir = std::env::temp_dir().join("FluxTweakers");
    let _ = fs::create_dir_all(&dir);
    let result_path = dir.join("ram_clean_result.txt");
    let mode = fs::read_to_string(dir.join("ram_action_mode.txt"))
        .unwrap_or_else(|_| "standby".to_string());
    let mode = mode.trim().to_string();

    // No modo "standby" medimos o tamanho real da Standby List antes/depois
    // (é isso que realmente mostra quantos GB foram liberados). No modo
    // "workingset" isso não se aplica (o que muda é o working set de cada
    // processo, não a standby list) — usamos memória disponível ali.
    let standby_before = if mode != "workingset" { standby_list_mb() } else { None };
    let avail_before = available_phys_mb();

    let trimmed_result: Result<u32, String> = if mode == "workingset" {
        Ok(trim_all_working_sets())
    } else {
        purge_standby_list()
    };

    let content = match trimmed_result {
        Ok(trimmed) => {
            let freed = if let (Some(before), Some(after)) = (standby_before, standby_list_mb()) {
                before.saturating_sub(after)
            } else {
                let after = available_phys_mb();
                after.saturating_sub(avail_before)
            };
            format!("OK|{freed}|trimmed={trimmed}")
        }
        Err(e) => format!("ERRO|{e}"),
    };
    let _ = fs::write(&result_path, content);
}

/// Registra a Tarefa Agendada elevada (dispara o próprio exe em modo worker)
/// só na primeira vez que algum botão de RAM é usado — pede UAC essa única
/// vez; chamadas seguintes são silenciosas.
#[tauri::command]
fn setup_ram_cleaner() -> Result<String, String> {
    #[cfg(target_os = "windows")]
    {
        let exe = std::env::current_exe()
            .map_err(|e| format!("Falha ao localizar o executável: {e}"))?;
        let exe_str = exe.to_string_lossy().to_string();

        // Cria (ou substitui) a tarefa agendada, rodando como o usuário atual
        // com privilégios mais altos, disparando o PRÓPRIO exe em modo worker.
        // O /SC ONCE /ST 00:00 é só um gatilho "dummy" — na prática a gente
        // sempre dispara via /run.
        let create_cmd = format!(
            "schtasks /Create /TN \"{name}\" /TR \"\\\"{exe}\\\" {flag}\" /SC ONCE /ST 00:00 /RL HIGHEST /F",
            name = RAM_CLEAN_TASK_NAME,
            exe = exe_str,
            flag = RAM_WORKER_FLAG,
        );

        let ps_launcher = format!(
            "Start-Process -FilePath 'cmd.exe' -ArgumentList '/c {cmd}' -Verb RunAs -WindowStyle Hidden -Wait",
            cmd = create_cmd.replace('\'', "''")
        );

        let result = Command::new("powershell")
            .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps_launcher])
            .creation_flags(CREATE_NO_WINDOW)
            .spawn()
            .and_then(|mut c| c.wait());

        match result {
            Ok(_) => Ok("Limpeza automática de RAM configurada".to_string()),
            Err(e) => Err(format!("Falha ao configurar: {e}")),
        }
    }
    #[cfg(not(target_os = "windows"))]
    {
        Ok("N/A".to_string())
    }
}

/// Dispara a limpeza (roda a tarefa agendada já configurada, que por sua vez
/// relança o próprio exe em modo worker). Não pede UAC de novo — a tarefa já
/// "nasceu" elevada. Espera o resultado real gravado pelo worker.
/// `mode`: "standby" (cache padrão) ou "workingset" (reduzir em uso).
#[tauri::command]
async fn run_ram_clean(mode: Option<String>) -> Result<String, String> {
    let dir = std::env::temp_dir().join("FluxTweakers");
    let _ = fs::create_dir_all(&dir);
    let mode_str = mode.unwrap_or_else(|| "standby".to_string());
    let _ = fs::write(dir.join("ram_action_mode.txt"), &mode_str);

    let result_path = dir.join("ram_clean_result.txt");
    let _ = fs::remove_file(&result_path); // limpa resultado antigo antes de rodar de novo

    // Confere não só se a tarefa existe, mas se ela já foi criada apontando
    // pro modo worker novo (--ram-clean-worker). Quem já tinha usado uma
    // versão antiga do app tem essa tarefa apontando pro PowerShell antigo —
    // sem checar o conteúdo, ela nunca seria substituída pela versão nativa.
    #[cfg(target_os = "windows")]
    let task_needs_setup = match Command::new("schtasks")
        .args(["/Query", "/TN", RAM_CLEAN_TASK_NAME, "/V", "/FO", "LIST"])
        .creation_flags(CREATE_NO_WINDOW)
        .output()
    {
        Ok(o) if o.status.success() => {
            let text = String::from_utf8_lossy(&o.stdout);
            !text.contains(RAM_WORKER_FLAG)
        }
        _ => true,
    };

    #[cfg(not(target_os = "windows"))]
    let task_needs_setup = false;

    // IMPORTANTE: setup_ram_cleaner() faz uma espera BLOQUEANTE (Start-Process
    // -Wait). Chamar isso direto aqui prenderia a mesma thread async que o
    // Tauri usa pra devolver a resposta pro app. Por isso roda em
    // spawn_blocking, só quando a tarefa precisa ser criada/atualizada.
    if task_needs_setup {
        tokio::task::spawn_blocking(setup_ram_cleaner)
            .await
            .map_err(|e| format!("Falha interna ao preparar a limpeza: {e}"))??;
    }

    #[cfg(target_os = "windows")]
    let spawn_result = Command::new("schtasks")
        .args(["/Run", "/TN", RAM_CLEAN_TASK_NAME])
        .creation_flags(CREATE_NO_WINDOW)
        .output();

    #[cfg(not(target_os = "windows"))]
    let spawn_result: std::io::Result<std::process::Output> =
        Err(std::io::Error::other("plataforma não suportada"));

    match spawn_result {
        Ok(o) if !o.status.success() => {
            return Err(format!(
                "Não consegui iniciar a tarefa de limpeza. ({})",
                String::from_utf8_lossy(&o.stderr).trim()
            ));
        }
        Err(e) => return Err(format!("Falha ao rodar limpeza: {e}")),
        _ => {}
    }

    // Agora o worker é um binário nativo compilado (sem PowerShell, sem
    // Add-Type, sem rescan de antivírus) — termina rápido. Ainda damos uma
    // margem generosa porque o Agendador de Tarefas do Windows não garante
    // velocidade nenhuma pra REALMENTE disparar o processo depois do
    // "schtasks /Run" (isso é assíncrono).
    for _ in 0..150 {
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        if let Ok(content) = fs::read_to_string(&result_path) {
            let content = content.trim();
            if let Some(rest) = content.strip_prefix("OK|") {
                let freed_part = rest.split('|').next().unwrap_or("0");
                let freed_mb: i64 = freed_part.parse().unwrap_or(0);
                return Ok(if freed_mb > 0 {
                    format!("RAM limpa — cerca de {freed_mb} MB liberados")
                } else {
                    "RAM limpa (cache já estava baixo, pouco a liberar)".to_string()
                });
            } else if let Some(err) = content.strip_prefix("ERRO|") {
                return Err(format!("O Windows recusou a limpeza ({err})"));
            }
        }
    }

    Err("A limpeza não respondeu a tempo — tente de novo".to_string())
}

// ===== Bordas arredondadas nativas (estilo Windows 11) =====
// O truque de CSS (transparência + border-radius) é frágil no Windows e nem
// sempre funciona. O jeito confiável — que Discord, Spotify e outros apps
// usam — é pedir pro próprio Windows arredondar a janela de verdade, via
// uma chamada direta à API do sistema (dwmapi.dll), sem precisar de
// nenhuma biblioteca externa.
#[cfg(target_os = "windows")]
#[link(name = "dwmapi")]
extern "system" {
    fn DwmSetWindowAttribute(
        hwnd: isize,
        dwattribute: u32,
        pvattribute: *const i32,
        cbattribute: u32,
    ) -> i32;
}

#[cfg(target_os = "windows")]
fn apply_native_rounded_corners(hwnd_raw: isize) {
    const DWMWA_WINDOW_CORNER_PREFERENCE: u32 = 33;
    const DWMWCP_ROUND: i32 = 2; // cantos arredondados "normais" do Windows 11
    unsafe {
        DwmSetWindowAttribute(
            hwnd_raw,
            DWMWA_WINDOW_CORNER_PREFERENCE,
            &DWMWCP_ROUND as *const i32,
            std::mem::size_of::<i32>() as u32,
        );
    }
}

/// Guarda em memória se o app deve minimizar pra bandeja (em vez de fechar de
/// verdade) quando o usuário clica no X. Carregado do disco na inicialização.
struct CloseBehaviorState(Mutex<bool>);

fn config_file_path(app: &tauri::AppHandle) -> Option<PathBuf> {
    let dir = app.path().app_config_dir().ok()?;
    let _ = fs::create_dir_all(&dir);
    Some(dir.join("settings.json"))
}

fn load_close_behavior(app: &tauri::AppHandle) -> bool {
    if let Some(path) = config_file_path(app) {
        if let Ok(content) = fs::read_to_string(&path) {
            if let Ok(json) = serde_json::from_str::<serde_json::Value>(&content) {
                if let Some(v) = json.get("close_to_tray").and_then(|v| v.as_bool()) {
                    return v;
                }
            }
        }
    }
    false // padrão: fechar o X fecha o app de verdade, igual sempre foi — só muda se o usuário ligar
}

/// Diz se o app está configurado pra minimizar pra bandeja ao fechar (em vez de sair).
#[tauri::command]
fn get_close_behavior(state: State<CloseBehaviorState>) -> bool {
    *state.0.lock().unwrap()
}

/// Liga/desliga "minimizar pra bandeja ao fechar" e salva a escolha no disco,
/// pra lembrar na próxima vez que o app abrir.
#[tauri::command]
fn set_close_behavior(app: tauri::AppHandle, state: State<CloseBehaviorState>, enabled: bool) -> Result<(), String> {
    *state.0.lock().unwrap() = enabled;
    if let Some(path) = config_file_path(&app) {
        let json = serde_json::json!({ "close_to_tray": enabled });
        fs::write(&path, json.to_string()).map_err(|e| format!("Não consegui salvar a preferência: {e}"))?;
    }
    Ok(())
}

/// Diz se o FluxTweakers está configurado pra abrir sozinho quando o Windows inicia.
#[tauri::command]
fn get_autostart_enabled(app: tauri::AppHandle) -> Result<bool, String> {
    use tauri_plugin_autostart::ManagerExt;
    app.autolaunch().is_enabled().map_err(|e| format!("Não consegui checar: {e}"))
}

/// Liga/desliga o app abrir sozinho com o Windows (usa a tarefa de inicialização
/// oficial do Windows, o mesmo mecanismo que outros programas usam).
#[tauri::command]
fn set_autostart_enabled(app: tauri::AppHandle, enabled: bool) -> Result<(), String> {
    use tauri_plugin_autostart::ManagerExt;
    let mgr = app.autolaunch();
    if enabled {
        mgr.enable().map_err(|e| format!("Não consegui ativar: {e}"))
    } else {
        mgr.disable().map_err(|e| format!("Não consegui desativar: {e}"))
    }
}

// ===================== App Tuner =====================
//
// Otimizações por aplicativo: limpar o cache (navegadores, Discord, Steam,
// Epic), subir a prioridade de processo (OBS e processo personalizado) e
// abrir as configurações certas (Modo Jogo do Windows e painel da placa de
// vídeo). Nada aqui mexe em senha, histórico ou login — só em pastas de cache.

#[derive(Clone, Copy)]
enum CacheSpec {
    /// limpa o CONTEÚDO dessa pasta
    Dir(&'static str),
    /// apaga as subpastas de <base> cujo nome começa com <prefixo>
    Prefix(&'static str, &'static str),
    /// navegador Chromium: limpa as subpastas indicadas de cada perfil
    Chromium(&'static str, &'static [&'static str]),
    /// limpa <sub> dentro de CADA subpasta de <base> (ex: perfis do Firefox)
    Under(&'static str, &'static str),
}

struct TunerDef {
    id: &'static str,
    name: &'static str,
    exes: &'static [&'static str],
    procs: &'static [&'static str],
    caches: &'static [CacheSpec],
    cache_label: Option<&'static str>,
    priority_label: Option<&'static str>,
}

