fn gamecfg_status_of(def: &GameCfgDef) -> GameCfgStatus {
    let path = gamecfg_path(def.id);
    GameCfgStatus {
        id: def.id.to_string(),
        name: def.name.to_string(),
        detected: path.is_some(),
        has_backup: path.as_ref().map(|p| gamecfg_backup_path(p).exists()).unwrap_or(false),
        config_path: path.map(|p| p.to_string_lossy().to_string()),
        running: gamecfg_running(def),
        note: def.note.to_string(),
    }
}

/// Lista os jogos suportados e se o arquivo de configuração de cada um existe neste PC.
#[tauri::command]
async fn gamecfg_list() -> Result<Vec<GameCfgStatus>, String> {
    tauri::async_runtime::spawn_blocking(|| GAMECFG.iter().map(gamecfg_status_of).collect::<Vec<_>>())
        .await
        .map_err(|e| format!("Falha interna: {e}"))
}

fn clear_readonly(p: &Path) {
    if let Ok(meta) = fs::metadata(p) {
        let mut perm = meta.permissions();
        if perm.readonly() { perm.set_readonly(false); let _ = fs::set_permissions(p, perm); }
    }
}

/// Roda UMA etapa da otimização de um jogo (o front chama uma por vez e anima):
/// "locate", "backup", "write", "windows" ou "verify".
#[tauri::command]
async fn gamecfg_step(game: String, step: String, tier: String, focus: String, refresh_hz: u32) -> Result<GameStepResult, String> {
    tauri::async_runtime::spawn_blocking(move || -> Result<GameStepResult, String> {
        let def = gamecfg_def(&game)?;
        let file = gamecfg_path(def.id);
        let need = || file.clone().ok_or_else(|| format!("Não achei a configuração do {}. Abra o jogo uma vez pra ele criar o arquivo e tente de novo.", def.name));
        let step_ok = |message: String, done: u32, total: u32, changes: Vec<GameChange>, path: Option<String>| Ok(GameStepResult { message, done, total, changes, path });
        match step.as_str() {
            "locate" => {
                let p = need()?;
                step_ok("Arquivo de configuração encontrado".into(), 1, 1, vec![], Some(p.to_string_lossy().to_string()))
            }
            "backup" => {
                let p = need()?;
                let b = gamecfg_backup_path(&p);
                if b.exists() {
                    step_ok("Cópia de segurança original já existia — foi mantida".into(), 1, 1, vec![], Some(b.to_string_lossy().to_string()))
                } else {
                    fs::copy(&p, &b).map_err(|e| format!("Não consegui criar a cópia de segurança: {e}"))?;
                    step_ok("Cópia de segurança criada ao lado do arquivo".into(), 1, 1, vec![], Some(b.to_string_lossy().to_string()))
                }
            }
            "write" => {
                let p = need()?;
                if gamecfg_running(def) {
                    return Err(format!("O {} está aberto. Feche o jogo primeiro — ele sobrescreve esse arquivo quando fecha.", def.name));
                }
                let mut content = fs::read_to_string(&p).map_err(|e| format!("Não consegui ler o arquivo: {e}"))?;
                let plan = gamecfg_plan(def.id, &tier, &focus, refresh_hz);
                let mut changes = Vec::new();
                let (mut applied, mut changed, mut skipped) = (0u32, 0u32, 0u32);
                let mut ini_batches: Vec<(&'static str, Vec<(String, String)>)> = Vec::new();
                for item in plan.iter() {
                    let before = cfg_get(def.format, &content, item);
                    if before.is_none() && !item.create { skipped += 1; continue; }
                    applied += 1;
                    if !before.as_deref().map(|b| cfg_same(item, b, &item.value)).unwrap_or(false) { changed += 1; }
                    changes.push(GameChange {
                        label: item.label.to_string(),
                        before: before.as_deref().map(|b| cfg_human(item.fmt, b)).unwrap_or_else(|| "—".to_string()),
                        after: cfg_human(item.fmt, &item.value),
                    });
                    if def.format == CfgFormat::Ini {
                        match ini_batches.iter_mut().find(|(sec, _)| *sec == item.section) {
                            Some((_, vals)) => vals.push((item.key.to_string(), item.value.clone())),
                            None => ini_batches.push((item.section, vec![(item.key.to_string(), item.value.clone())])),
                        }
                    } else {
                        content = cfg_set_single(def.format, &content, item);
                    }
                }
                for (sec, vals) in ini_batches.iter() { content = ini_set(&content, sec, vals); }
                if applied == 0 {
                    return Err(format!("Nenhuma das opções conhecidas existe no arquivo do {} — a versão do jogo deve guardar de outro jeito. Nada foi alterado.", def.name));
                }
                clear_readonly(&p);
                fs::write(&p, content).map_err(|e| format!("Não consegui salvar o arquivo: {e}"))?;
                let extra = if skipped > 0 { format!(" ({skipped} opções não existem na sua versão e foram ignoradas)") } else { String::new() };
                step_ok(format!("{changed} de {applied} ajustes mudaram{extra}"), changed, applied, changes, Some(p.to_string_lossy().to_string()))
            }
            "windows" => {
                let exe = match gamecfg_exe(def.id) {
                    Some(e) => e,
                    None => return step_ok("Sem ajustes extras do Windows pra esse jogo — pulei".into(), 0, 0, vec![], None),
                };
                let exe_s = exe.to_string_lossy().to_string();
                let ok = game_reg_apply(&exe_s);
                step_ok(format!("{ok} de 2 opções do Windows aplicadas (GPU dedicada e tela cheia sem otimizações)"), ok, 2, vec![], Some(exe_s))
            }
            "verify" => {
                let p = need()?;
                let content = fs::read_to_string(&p).map_err(|e| format!("Não consegui reler o arquivo: {e}"))?;
                let plan = gamecfg_plan(def.id, &tier, &focus, refresh_hz);
                let mut total = 0u32;
                let mut ok = 0u32;
                for item in plan.iter() {
                    match cfg_get(def.format, &content, item) {
                        Some(v) => { total += 1; if cfg_same(item, &v, &item.value) { ok += 1; } }
                        None => { if item.create { total += 1; } }
                    }
                }
                if ok == total {
                    step_ok(format!("Conferi o arquivo: {ok} de {total} valores confirmados"), ok, total, vec![], Some(p.to_string_lossy().to_string()))
                } else {
                    Err(format!("Só {ok} de {total} valores ficaram gravados — o {} pode ter reescrito o arquivo.", def.name))
                }
            }
            _ => Err("Etapa desconhecida".to_string()),
        }
    })
    .await
    .map_err(|e| format!("Falha interna: {e}"))?
}

const GAME_WIN_JOBS: [(&str, &str); 2] = [
    ("HKCU\\Software\\Microsoft\\DirectX\\UserGpuPreference", "GpuPreference=2;"),
    ("HKCU\\Software\\Microsoft\\Windows NT\\CurrentVersion\\AppCompatFlags\\Layers", "~ DISABLEDXMAXIMIZEDWINDOWEDMODE"),
];

/// Liga "GPU de alto desempenho" e desliga as otimizações de tela cheia pro .exe (sem admin).
fn game_reg_apply(exe: &str) -> u32 {
    let mut ok = 0u32;
    for (key, data) in GAME_WIN_JOBS {
        let mut cmd = Command::new("reg");
        cmd.args(["add", key, "/v", exe, "/t", "REG_SZ", "/d", data, "/f"]);
        #[cfg(target_os = "windows")]
        { cmd.creation_flags(CREATE_NO_WINDOW); }
        if cmd.output().map(|o| o.status.success()).unwrap_or(false) { ok += 1; }
    }
    ok
}

fn game_reg_verify(exe: &str) -> u32 {
    let mut ok = 0u32;
    for (key, expect) in GAME_WIN_JOBS {
        let mut cmd = Command::new("reg");
        cmd.args(["query", key, "/v", exe]);
        #[cfg(target_os = "windows")]
        { cmd.creation_flags(CREATE_NO_WINDOW); }
        if let Ok(o) = cmd.output() {
            if o.status.success() && String::from_utf8_lossy(&o.stdout).contains(expect) { ok += 1; }
        }
    }
    ok
}

#[derive(Serialize)]
struct GamePreviewRow {
    label: String,
    current: String,
    recommended: String,
    same: bool,
}

/// Mostra, SEM gravar nada, como está a configuração do jogo agora versus o recomendado pro seu PC.
#[tauri::command]
async fn gamecfg_preview(game: String, tier: String, focus: String, refresh_hz: u32) -> Result<Vec<GamePreviewRow>, String> {
    tauri::async_runtime::spawn_blocking(move || -> Result<Vec<GamePreviewRow>, String> {
        let def = gamecfg_def(&game)?;
        let p = gamecfg_path(def.id).ok_or_else(|| format!("Não achei a configuração do {}.", def.name))?;
        let content = fs::read_to_string(&p).map_err(|e| format!("Não consegui ler o arquivo: {e}"))?;
        let mut rows = Vec::new();
        for item in gamecfg_plan(def.id, &tier, &focus, refresh_hz).iter() {
            let cur = cfg_get(def.format, &content, item);
            if cur.is_none() && !item.create { continue; }
            let same = cur.as_deref().map(|c| cfg_same(item, c, &item.value)).unwrap_or(false);
            rows.push(GamePreviewRow {
                label: item.label.to_string(),
                current: cur.as_deref().map(|c| cfg_human(item.fmt, c)).unwrap_or_else(|| "—".to_string()),
                recommended: cfg_human(item.fmt, &item.value),
                same,
            });
        }
        Ok(rows)
    })
    .await
    .map_err(|e| format!("Falha interna: {e}"))?
}

/// Ajustes do Windows pra QUALQUER jogo (por .exe): "apply" ou "verify".
#[tauri::command]
async fn game_windows_tweak(exe_path: String, step: String) -> Result<GameStepResult, String> {
    tauri::async_runtime::spawn_blocking(move || -> Result<GameStepResult, String> {
        if !exe_path.to_lowercase().ends_with(".exe") || !Path::new(&exe_path).exists() {
            return Err("Não achei o executável do jogo.".to_string());
        }
        match step.as_str() {
            "apply" => {
                let ok = game_reg_apply(&exe_path);
                Ok(GameStepResult { message: format!("{ok} de 2 opções do Windows aplicadas (GPU dedicada e tela cheia sem otimizações)"), done: ok, total: 2, changes: vec![], path: Some(exe_path) })
            }
            "verify" => {
                let ok = game_reg_verify(&exe_path);
                if ok == 2 {
                    Ok(GameStepResult { message: "Conferi no registro: 2 de 2 opções gravadas".into(), done: 2, total: 2, changes: vec![], path: Some(exe_path) })
                } else {
                    Err(format!("Só {ok} de 2 opções ficaram gravadas no registro."))
                }
            }
            _ => Err("Etapa desconhecida".to_string()),
        }
    })
    .await
    .map_err(|e| format!("Falha interna: {e}"))?
}

/// Abre o arquivo de configuração do jogo no Bloco de Notas.
#[tauri::command]
fn gamecfg_open(game: String) -> Result<String, String> {
    let def = gamecfg_def(&game)?;
    let p = gamecfg_path(def.id).ok_or_else(|| format!("Não achei a configuração do {}. Abra o jogo uma vez e tente de novo.", def.name))?;
    let mut cmd = Command::new("notepad.exe");
    cmd.arg(&p);
    cmd.spawn().map_err(|e| format!("Não consegui abrir o Bloco de Notas: {e}"))?;
    Ok(p.to_string_lossy().to_string())
}

/// Volta o arquivo do jogo pra cópia de segurança original.
#[tauri::command]
fn gamecfg_restore(game: String) -> Result<String, String> {
    let def = gamecfg_def(&game)?;
    let p = gamecfg_path(def.id).ok_or_else(|| format!("Não achei a configuração do {}.", def.name))?;
    let b = gamecfg_backup_path(&p);
    if !b.exists() { return Err("Ainda não existe cópia de segurança — otimize uma vez primeiro.".to_string()); }
    if gamecfg_running(def) { return Err(format!("Feche o {} antes de restaurar.", def.name)); }
    clear_readonly(&p);
    fs::copy(&b, &p).map_err(|e| format!("Não consegui restaurar: {e}"))?;
    Ok(format!("Configuração original do {} restaurada", def.name))
}

/// Ícones reais dos jogos (extraídos dos .exe). Devolve índice -> data URL PNG.
#[tauri::command]
async fn game_icons(paths: Vec<String>) -> Result<std::collections::HashMap<String, String>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let mut map = std::collections::HashMap::new();
        let list: Vec<String> = paths.iter().enumerate()
            .filter(|(_, p)| p.to_lowercase().ends_with(".exe") && Path::new(p.as_str()).exists())
            .map(|(i, p)| format!("'{}|{}'", i, p.replace('\'', "''")))
            .collect();
        if list.is_empty() { return map; }
        let ps = format!(
            "Add-Type -AssemblyName System.Drawing; $items = @({}); foreach($it in $items){{ $p = $it.Split('|',2); try {{ $ic = [System.Drawing.Icon]::ExtractAssociatedIcon($p[1]); $b = $ic.ToBitmap(); $ms = New-Object System.IO.MemoryStream; $b.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png); $p[0] + '|' + [Convert]::ToBase64String($ms.ToArray()) }} catch {{}} }}",
            list.join(",")
        );
        #[cfg(target_os = "windows")]
        {
            if let Ok(o) = Command::new("powershell").args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps]).creation_flags(CREATE_NO_WINDOW).output() {
                for line in String::from_utf8_lossy(&o.stdout).lines() {
                    if let Some((id, b64)) = line.trim().split_once('|') {
                        if !b64.is_empty() { map.insert(id.to_string(), format!("data:image/png;base64,{b64}")); }
                    }
                }
            }
        }
        #[cfg(not(target_os = "windows"))]
        { let _ = ps; }
        map
    })
    .await
    .map_err(|e| format!("Falha interna: {e}"))
}

fn main() {
    #[cfg(target_os = "windows")]
    {
        if std::env::args().any(|a| a == RAM_WORKER_FLAG) {
            ram_clean_worker_entrypoint();
            return;
        }
    }

    tauri::Builder::default()
        .plugin(tauri_plugin_updater::Builder::new().build())
        .plugin(tauri_plugin_process::init())
        .plugin(tauri_plugin_autostart::init(tauri_plugin_autostart::MacosLauncher::LaunchAgent, None))
        .manage(SysState(Mutex::new(System::new_all())))
        .manage(PdhState(Mutex::new(None)))
        .invoke_handler(tauri::generate_handler![run_bat_script, get_system_stats, setup_ram_cleaner, run_ram_clean, get_hardware_info, get_ram_details, run_diagnostics, scan_installed_games, analyze_game, apply_game_graphics_preset, run_deep_scan, get_close_behavior, set_close_behavior, get_autostart_enabled, set_autostart_enabled, list_power_plans, extract_fluxtweakers_plan_file, kill_processes_by_name, set_power_plan, apptuner_overview, apptuner_action, apptuner_set_priority, apptuner_open, apptuner_icons, apptuner_pick_exe, apptuner_optimize_step, apptuner_startup_list, apptuner_startup_toggle, apptuner_set_affinity, dns_overview, dns_benchmark, dns_probe_provider, dns_apply, dns_restore, get_machine_id, game_pc_profile, game_analyze, gamecfg_list, gamecfg_step, gamecfg_preview, game_windows_tweak, gamecfg_open, gamecfg_restore, game_icons])
        .setup(|app| {
            let close_to_tray = load_close_behavior(&app.handle());
            app.manage(CloseBehaviorState(Mutex::new(close_to_tray)));

            // Abre a conexão PDH (GPU/CPU-frequência/disco) UMA ÚNICA VEZ aqui
            // na inicialização — ver "Monitor nativo via PDH" mais abaixo.
            #[cfg(target_os = "windows")]
            {
                *app.state::<PdhState>().0.lock().unwrap() = init_pdh_monitor();
            }

            // Monitor de sistema rodando de verdade em segundo plano — não
            // depende da janela estar em foco (diferente de um timer no
            // JavaScript da página, que o Windows/WebView2 desacelera bastante
            // quando a janela perde o foco ou fica atrás de outra, causando
            // números "congelados" e desatualizados ao comparar com o
            // Gerenciador de Tarefas). Empurra os números pro frontend via
            // evento assim que lê, ao vés de esperar o frontend perguntar.
            // GPU/CPU-frequência/disco agora são lidos nativamente via PDH
            // (sem abrir PowerShell), então dá pra ler em TODO ciclo, no mesmo
            // ritmo de CPU/RAM — praticamente em tempo real.
            {
                let app_handle = app.handle().clone();
                tauri::async_runtime::spawn(async move {
                    loop {
                        tokio::time::sleep(std::time::Duration::from_millis(1000)).await;
                        let sys_state = app_handle.state::<SysState>();
                        let pdh_state = app_handle.state::<PdhState>();
                        if let Ok(stats) = compute_system_stats(&sys_state, &pdh_state, true).await {
                            let _ = app_handle.emit("system-stats", stats);
                        }
                    }
                });
            }

            #[cfg(target_os = "windows")]
            {
                if let Some(window) = app.get_webview_window("main") {
                    if let Ok(hwnd) = window.hwnd() {
                        apply_native_rounded_corners(hwnd.0 as isize);
                    }
                }
            }

            // Ícone na bandeja do sistema com menu (Mostrar / Sair) — permite
            // reabrir o app quando ele estiver minimizado em segundo plano.
            use tauri::menu::{Menu, MenuItem};
            use tauri::tray::TrayIconBuilder;
            let show_item = MenuItem::with_id(app, "show", "Mostrar FluxTweakers", true, None::<&str>)?;
            let quit_item = MenuItem::with_id(app, "quit", "Sair", true, None::<&str>)?;
            let tray_menu = Menu::with_items(app, &[&show_item, &quit_item])?;
            let default_icon = app.default_window_icon().cloned();
            let mut tray_builder = TrayIconBuilder::new()
                .menu(&tray_menu)
                .tooltip("FluxTweakers")
                .on_menu_event(|app, event| {
                    match event.id.as_ref() {
                        "show" => {
                            if let Some(w) = app.get_webview_window("main") {
                                let _ = w.show();
                                let _ = w.set_focus();
                            }
                        }
                        "quit" => { app.exit(0); }
                        _ => {}
                    }
                })
                .on_tray_icon_event(|tray, event| {
                    if let tauri::tray::TrayIconEvent::Click {
                        button: tauri::tray::MouseButton::Left,
                        button_state: tauri::tray::MouseButtonState::Up, ..
                    } = event {
                        let app = tray.app_handle();
                        if let Some(w) = app.get_webview_window("main") {
                            let _ = w.show();
                            let _ = w.set_focus();
                        }
                    }
                });
            if let Some(icon) = default_icon {
                tray_builder = tray_builder.icon(icon);
            }
            let _tray = tray_builder.build(app)?;

            // Intercepta o clique no X: se "minimizar pra bandeja" estiver ligado,
            // só esconde a janela em vez de fechar o app de verdade.
            if let Some(window) = app.get_webview_window("main") {
                let app_handle = app.handle().clone();
                window.on_window_event(move |event| {
                    if let tauri::WindowEvent::CloseRequested { api, .. } = event {
                        let state = app_handle.state::<CloseBehaviorState>();
                        let should_hide = *state.0.lock().unwrap();
                        if should_hide {
                            api.prevent_close();
                            if let Some(w) = app_handle.get_webview_window("main") {
                                let _ = w.hide();
                            }
                        }
                    }
                });
            }

            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("erro ao rodar o app By Dgeras");
}


